(* [comment removed for export] *)
Lemma put_loop : forall (k : nat) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config),
  put_static H MX CX sp tp LB0 P E lo B p0 R bs -> p < p0 + Z.of_nat (length bs) -> p0 + Z.of_nat (length bs) - p <= Z.of_nat k ->
  put_at H MX CX PUT_DISP (ak_disp p) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p cf ->
  hs_SR H (put_post0 H MX CX ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb) cf.
Proof.
  induction k as [|k IH]; intros until cf; intros STAT PLT MEAS AT; [exfalso; lia|].
  eapply (hh_seq H HH); [eapply put_disp_round; [exact STAT | exact PLT | exact AT] |].
  intros cf' [DONE | (p' & LT & AT')]; [apply (hh_done H HH); exact DONE |].
  apply (IH ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p' cf'); [exact STAT | lia | rewrite Nat2Z.inj_succ in MEAS; lia | exact AT'].
Qed.

(* [comment removed for export] *)
Lemma put_dtor_facts : forall (sp : word) P p0 bs LB0 L0 es0 h0 mb d m,
  PutU P p0 bs mb d m -> PutL sp P p0 bs LB0 L0 es0 h0 d ->
  HdrOwnP (ps_LBn d ++ LB0) (ps_h d) /\ HdrDisjP (ps_em d) (ps_h d) /\ BodyDisjP (ps_em d) (ps_h d) (ps_es d).
Proof.
  intros sp P p0 bs LB0 L0 es0 h0 mb d m U L.
  destruct U as (FC & _ & _ & MB & _).
  destruct L as (PCOK & OWN & MOWN & HOWN & EH & ESH & NEW & NEWB & WINL & WINB & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HNEW & HL8 & SK62 & AOWN & LS & ESS).
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
  destruct HDJ as (J1 & J2 & J3 & J4 & J5).
  split; [exact HOWN|]. split.
  - split; [| split].
    + intros ML. destruct (ps_em d !! hv_mp (ps_h d)) as [dd|] eqn:Ld; [exfalso | reflexivity].
      destruct (J2 ltac:(lia) (hv_mp (ps_h d)) ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity)); lia.
    + intros TL. destruct (ps_em d !! hv_tp (ps_h d)) as [dd|] eqn:Ld; [exfalso | reflexivity].
      destruct (J1 ltac:(lia) (hv_tp (ps_h d)) ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity)); lia.
    + intros ML TL. destruct (J5 ltac:(lia) ltac:(lia)); lia.
  - intros x s IN. pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ. split; [| split].
    + destruct (ps_em d !! x) as [dd|] eqn:Ld; [exfalso | reflexivity].
      destruct (DFB x x s ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity) IN); lia.
    + intros ML. destruct (J4 ltac:(lia) x s IN); lia.
    + intros TL. destruct (J3 ltac:(lia) x s IN); lia.
Qed.
